INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(17901, 'Jeremiah 3:12', 'Jeremiah', 3, 12, '&nbsp;هغۀ ما ته وفرمائيل چې، ”د شمال طرف ته لاړ شه او هغوئ ته ووايه، اے بې‌ايمانه اِسرائيله، مالِک خُدائ فرمائى ما ته راواپس شه. زۀ به په غصې سره نور تا ته نۀ ګورم، ځکه چې زۀ رحم کوونکے يم، مالِک خُدائ فرمائى، او نۀ به زۀ د تل دپاره تا ته غصه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17902, 'Jeremiah 3:13', 'Jeremiah', 3, 13, '&nbsp;تۀ صرف د خپلو ګناهونو اقرار وکړه چې ګناهګار يم او تا د خپل مالِک خُدائ خلاف سرکشى کړې ده، او تا د هرې شنې ونې د لاندې د پردو بُتانو عبادت کړے دے او زما د کلام تابعدارى دې نۀ ده کړې، مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17903, 'Jeremiah 3:14', 'Jeremiah', 3, 14, '&nbsp;اے بې‌ايمانه خلقو، راواپس شئ ځکه چې زۀ ستاسو مالِک يم. زۀ به ستاسو د ښاريې نه يو او د هرې قبيلې نه دوه دوه کسان خوښ کړم او صيون ښار ته به مو واپس راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17904, 'Jeremiah 3:15', 'Jeremiah', 3, 15, '&nbsp;زۀ به تاسو له د شپونکو په شان مشران درکړم چې زما سوچ لرى او تاسو ته په عِلم او عقل سره هدايت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17905, 'Jeremiah 3:16', 'Jeremiah', 3, 16, '&nbsp;نو کله چې ستاسو د خلقو شمېر په هغه مُلک کښې ډېر شى، مالِک خُدائ فرمائى، نو تاسو به په هغه ورځو کښې د خُدائ د لوظ صندوق ذکر نۀ کوئ او هم به ستاسو خيال ته دا نور نۀ راځى، او نۀ به هغه يادوئ، او نۀ به د هغې د ضرورت احساس تاسو ته کيږى، او نۀ به هغه دوباره جوړ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17906, 'Jeremiah 3:17', 'Jeremiah', 3, 17, '&nbsp;نو په دغه وخت کښې به دوئ يروشلم ته د ”مالِک خُدائ تخت“ ووائى، او ټول قومونه به په يروشلم کښې راټول شى او د مالِک خُدائ نوم له به عزت ورکړى. او دوئ به نور د خپل سرکشه او شريره زړونو پيروى نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17907, 'Jeremiah 3:18', 'Jeremiah', 3, 18, '&nbsp;نو په دغه ورځو کښې به د يهوداه خاندان د اِسرائيل د خاندان سره يوځائ شى او په شريکه به دوئ د شمال د جلاوطنۍ د مُلک نه هغه مُلک ته واپس راشى کوم چې ما ستاسو پلار نيکۀ له په ميراث کښې ورکړے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17908, 'Jeremiah 3:19', 'Jeremiah', 3, 19, '&nbsp;”مالِک خُدائ په خپله فرمائى چې اے بنى اِسرائيله، ما غوښتل چې زۀ تا سره د خپل بچى په شان سلوک وکړم او د خپلې خوښې مُلک او زمکه درکړم، چې د نورو مُلکونو په نسبت ښکلې او شانداره وى. زما دا خيال وو چې تۀ به ما ته خپل پلار ووائې او زما نه به وانۀ وړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17909, 'Jeremiah 3:20', 'Jeremiah', 3, 20, '&nbsp;خو تۀ ما سره بې‌وفا شوې د هغې ښځې په شان څوک چې خپل خاوند سره بې‌وفا وى. مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17910, 'Jeremiah 3:21', 'Jeremiah', 3, 21, '&nbsp;د خُشکو غرونو په اوچتو سرونو باندې د بنى اِسرائيليانو د ژړا او فرياد شور اورېدلے شى، ځکه چې هغوئ غلطه لار اختيار کړې ده او خپل مالِک خُدائ يې هېر کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17911, 'Jeremiah 3:22', 'Jeremiah', 3, 22, '&nbsp;اے بې‌وفا بچو ما ته راواپس شئ زۀ به ستاسو بې‌وفائى له شفا درکړم. اے مالِکه خُدايه، مونږ به تا ته راواپس کيږُو ځکه چې تۀ مالِک خُدائ زمونږ خُدائ پاک يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17912, 'Jeremiah 3:23', 'Jeremiah', 3, 23, '&nbsp;مونږ چې په زور شور سره د غرونو او غونډو په سرونو د بُتانو کوم عبادت کړے دے دا په رښتيا سره دوکه وه، د بنى اِسرائيل خلاصون په يقين سره صرف په مالِک خُدائ زمونږ خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17913, 'Jeremiah 3:24', 'Jeremiah', 3, 24, '&nbsp;د اول نه تر آخره پورې دې شرمناک د بعل بُت زمونږ د پلار نيکۀ د محنت مېوه، د دوئ رمې او څاروى، زامن او لوڼه ټول قبضه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17914, 'Jeremiah 3:25', 'Jeremiah', 3, 25, '&nbsp;مونږ له په کار دى چې بې‌عزتى او شرم قبول کړُو او په شرمونو پټ شُو. ځکه چې مونږ د خپل پلار نيکۀ سره د خپل مالِک خُدائ زمونږ خُدائ پاک په خلاف ګناه کړې ده. د اول نه تر آخره پورې مونږ د خپل مالِک خُدائ پيروى نۀ ده کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17915, 'Jeremiah 4:1', 'Jeremiah', 4, 1, '&nbsp;مالِک خُدائ فرمائى، ”اے بنى اِسرائيلو، کۀ چرې تاسو واپس ما له راتلل غواړئ نو ما له واپس راشئ. کۀ چرې تاسو خپل پليت بُتان زما د نظر نه اخوا کړئ او نور نۀ ګمراه کېږئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17916, 'Jeremiah 4:2', 'Jeremiah', 4, 2, '&nbsp;کله چې تاسو قسم خورئ چې، ”مالِک خُدائ ژوندے دے“ نو په رښتيا، اِنصاف، او صداقت سره خپله وعده پوره کوئ، نو بيا به تۀ د دُنيا قومونو ته د برکت ذريعه وګرځې او ټول قومونه به ستا په وجه زما نوم ته جلال ورکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17917, 'Jeremiah 4:3', 'Jeremiah', 4, 3, '&nbsp;مالِک خُدائ د يهوداه او يروشلم خلقو ته فرمائى، ”د خپلو زړونو په سخته زمکه کښې يوه وکړئ او په ازغو کښې تخم مۀ کَرئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17918, 'Jeremiah 4:4', 'Jeremiah', 4, 4, '&nbsp;اے د يهوداه او د يروشلم خلقو خپل زړونه ما ته وقف کړئ، هسې نه ستاسو د بدو اعمالو په وجه زما د قهر اور بل شى نو هغه به تاسو مکمل وسوزوى او بيا به داسې هيڅ څوک نۀ وى چې هغه مړ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17919, 'Jeremiah 4:5', 'Jeremiah', 4, 5, '&nbsp;په يهوداه کښې اعلان وکړئ او يروشلم ته اِطلاع ورکړئ او ورته ووايئ، ”په ټول مُلک کښې بيګل وغږوئ. په زوره چغې ووهئ. او ورته ووايئ، راشئ، محفوظو ښارونو کښې پناه واخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17920, 'Jeremiah 4:6', 'Jeremiah', 4, 6, '&nbsp;د صيون طرف ته د تېښتې دپاره جنډا اوچته کړئ او په منډه محفوظ ځائ ته وتښتئ. ځکه چې زۀ د شمال د خوا نه افت او سخته تباهى راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17921, 'Jeremiah 4:7', 'Jeremiah', 4, 7, '&nbsp;د ځنګل د زمرى په شان د قومونو سخت او تباه کوونکے دشمن د خپل غار نه راووتو، هغه د خپل ځائ نه راروان دے چې ستاسو زمکه تباه کړى او ستاسو ښارونه به وران ويجاړ کړى او هغه به خالى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17922, 'Jeremiah 4:8', 'Jeremiah', 4, 8, '&nbsp;د ماتم او ټاټ جامې واغوندئ، ژړا او وير وکړئ. ځکه چې د مالِک خُدائ سخت قهر تر اوسه پورې په مونږ باندې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17923, 'Jeremiah 4:9', 'Jeremiah', 4, 9, '&nbsp;مالِک خُدائ فرمائى، په هغه ورځ به بادشاهان او آفسران حوصله بائيلى، د اِمامانو به د يرې نه وېښتۀ ودريږى او پېغمبران به د يرې نه جام پاتې شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17924, 'Jeremiah 4:10', 'Jeremiah', 4, 10, '&nbsp;بيا ما ووئيل، ”اے قادر مطلق خُدايه، دا خلق او يروشلم ستا په هغه وينا دوکه شُو کومه چې تا کړې وه چې تاسو به پوره په امن کښې اوسېږئ، خو په دې کښې تُوره زمونږ د مرۍ دپاسه سوره شوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17925, 'Jeremiah 4:11', 'Jeremiah', 4, 11, '&nbsp;په دغه وخت کښې به دې خلقو او يروشلم ته ووئيلے شى چې، ”زما عزيزانو. د صحرا د اوچتو غونډو نه به سوزونکى هوا په تاسو راشى، دا به هغه ښۀ هوا نۀ وى چې دانې د بوسو نه جدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17926, 'Jeremiah 4:12', 'Jeremiah', 4, 12, '&nbsp;خو زما د خوا نه به ډېره تېزه هوا لکه د طوفان راشى نو اوس زۀ خپله فېصله او سزا د ستاسو په خلاف اعلانوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17927, 'Jeremiah 4:13', 'Jeremiah', 4, 13, '&nbsp;وګورئ، دشمن لکه د وريځو په شان زمونږ خوا ته راروان دے. د هغۀ جنګى ګاډۍ لکه د تېز طوفان په شان راروانې دى او د هغۀ آسونه د باز نه تېز دى. په مونږ افسوس، مونږ تباه او برباد شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17928, 'Jeremiah 4:14', 'Jeremiah', 4, 14, '&nbsp;اے يروشلمه، خپل زړۀ د ګناه او شرارت نه ووينځه، نو دغه شان به تۀ خلاصون حاصل کړئ. ترڅو پورې به تۀ په خپل زړۀ کښې د ګناه سوچونه کوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17929, 'Jeremiah 4:15', 'Jeremiah', 4, 15, '&nbsp;يو آواز د دان نه د بد خبر اعلان کوى او د اِفرائيم د غونډو نه د افت راتلو خبردارے ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17930, 'Jeremiah 4:16', 'Jeremiah', 4, 16, '&nbsp;د دُنيا غېر قومونو ته خبردارے ورکړه او يروشلم ته اعلان وکړه چې، ”ستاسو او د يهوداه د ښارونو خلاف د جنګ چغې وهونکے غټ لښکر د لرې مُلک نه راروان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17931, 'Jeremiah 4:17', 'Jeremiah', 4, 17, '&nbsp;دوئ به يروشلم داسې محاصره کړى لکه چې سړى د پټى حفاظت کوى، ځکه چې د دې خلقو د مالِک خُدائ نه سرکشى کړې ده، مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17932, 'Jeremiah 4:18', 'Jeremiah', 4, 18, '&nbsp;اے يهوداه، ستا خپل چال چلن دا مصيبت په تا نازل کړے دے. دا ستا سزا ده. او دا څومره ترخه ده. او دا څومره زړۀ سورے کوونکې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17933, 'Jeremiah 4:19', 'Jeremiah', 4, 19, '&nbsp;واى! واى! زۀ په درد او مصيبت کښې راګېر شوم. زړۀ مې درزيږى نور زۀ چپ پاتې کېدے نۀ شم. ځکه چې ما د دشمن د جنګ د بيګل آوازونه واورېدل او د دوئ د جنګ د ناروا شور آوازونه مې واورېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17934, 'Jeremiah 4:20', 'Jeremiah', 4, 20, '&nbsp;د تباهۍ او بربادۍ چپې پرله پسې په مُلک راخورې شوې، هر طرف ته مُلک تباه شو، ناګهانه زما خېمې تباه شوې، او په يوه لحظه کښې زما پناه ګاه تباه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17935, 'Jeremiah 4:21', 'Jeremiah', 4, 21, '&nbsp;ترڅو پورې به زۀ د جنګونو دا جنډې ګورم او ترڅو پورې به د بيګلو آوازونه اورم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17936, 'Jeremiah 4:22', 'Jeremiah', 4, 22, '&nbsp;مالِک خُدائ فرمائى، ”زما خلق کم عقل دى، هغوئ ما نۀ پېژنى. هغوئ لکه د ناپوهه ماشومانو په شان عقل نۀ لرى. په ورانى کښې ډېر پوهه دى خو په نېکۍ کولو نۀ پوهيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17937, 'Jeremiah 4:23', 'Jeremiah', 4, 23, '&nbsp;ما په زمکه باندې نظر واچولو زمکه خالى وه او هيڅ په کښې نۀ وُو، او چې آسمان ته مې وکتل نو هلته هم رڼا نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17938, 'Jeremiah 4:24', 'Jeremiah', 4, 24, '&nbsp;په غرونو باندې مې نظر واچولو نو دا خوځېدل او غونډو هم ټالونه خوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17939, 'Jeremiah 4:25', 'Jeremiah', 4, 25, '&nbsp;ما هرې خوا ته وليدل خو څوک هم راته ښکاره نۀ شو، او ټول مارغان هم تښتېدلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17940, 'Jeremiah 4:26', 'Jeremiah', 4, 26, '&nbsp;ما هغه زرخيزه پټى وليدل چې په شاړو بدل شوى وُو. او ښارونه وران ويجاړ شوى وُو، چې د مالِک خُدائ په يروونکې غصې سره چخڼى شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17941, 'Jeremiah 4:27', 'Jeremiah', 4, 27, '&nbsp;مالِک خُدائ فرمائى، ”ټوله زمکه به تباه شى خو زۀ به بيا هم دا په پوره توګه نۀ تباه کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17942, 'Jeremiah 4:28', 'Jeremiah', 4, 28, '&nbsp;نو په دې وجه به زمکه ماتم کوى، او بره آسمان به تک تور شى. ځکه چې ما دا وفرمائيل او د خپلې خبرې نه به وانۀ وړم. ما دا فېصله کړې ده دا به بدله نۀ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17943, 'Jeremiah 4:29', 'Jeremiah', 4, 29, '&nbsp;د ښار خلق چې د فوجيانو د آسونو او د غشو ليندو شور او درزار واورى نو تښتى. او هر يو کس ځنګلونو او غرونو ته پناه وړى او هر يو ښار به خالى شى او هيڅ څوک به پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17944, 'Jeremiah 4:30', 'Jeremiah', 4, 30, '&nbsp;اے تباه او لوټ شويه ښاره، تۀ اوس څۀ کوې؟ تۀ ولې سرې جامې اچوې او د سرو کالے استعمالوې او سترګې توروې؟ تۀ هسې فضول خپل ځان سينګاروې. ستا عاشقانو تۀ نامنظوره کړے يې او ستا نه نفرت کوى او هغوئ ستا وژل غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17945, 'Jeremiah 4:31', 'Jeremiah', 4, 31, '&nbsp;ما داسې ژړا واورېدله لکه چې د يوې ښځې د ماشوم د پېدا کېدو وخت وى، داسې زبيرګى وُو لکه څنګه چې يوه ښځه په وړومبى ماشوم کوى. زما لور صيون ژاړى او سلګۍ وهى، او خپل لاس يې د امداد دپاره اوږد کړے دے او وائى، ”افسوس په ما! زۀ تباه شوم او چې د خپلو قاتلانو د وړاندې تکه زېړه او بې‌وسه شوې يمه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17946, 'Jeremiah 5:1', 'Jeremiah', 5, 1, '&nbsp;د يروشلم په کوڅو کښې ښکته پورته منډې ووهئ. اخوا ديخوا په غور سره وګورئ او په چوکونو کښې لټون وکړئ. کۀ چرې تاسو داسې يو کس هم پېدا کړئ چې هغه صداقت او اِنصاف کوى او په رښتياو پسې ګرځى، نو زۀ به دا ښار نۀ تباه کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17947, 'Jeremiah 5:2', 'Jeremiah', 5, 2, '&nbsp;کۀ څۀ هم چې دوئ زما په نوم قسم خورى چې، ”مالِک خُدائ ژوندے دے،“ خو بيا هم دوئ دروغ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17948, 'Jeremiah 5:3', 'Jeremiah', 5, 3, '&nbsp;اے مالِکه خُدايه ستا سترګې صداقت ليدل غواړى. کۀ څۀ هم چې تا دوئ ووهل خو دوئ ته پرې څۀ خفګان ونۀ رسېدو، تا هغوئ ته سزا ورکړه خو بيا هم دوئ اصلاح نۀ شُو. او دوئ خپل زړونه د کاڼى نه هم سخت کړل او د توبې ويستلو نه يې اِنکار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17949, 'Jeremiah 5:4', 'Jeremiah', 5, 4, '&nbsp;نو بيا ما سوچ وکړو چې، ”دا خو غريبانان او جاهله مخلوق دے، دوئ ځکه بې‌وقوفه کارونه کوى چې د مالِک خُدائ لار نۀ پېژنى او د هغۀ د حکمونو نه ناواقفه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17950, 'Jeremiah 5:5', 'Jeremiah', 5, 5, '&nbsp;نو زۀ به د دوئ مشرانو له لاړ شم او هغوئ سره به خبرې وکړم. نو دوئ به ضرور د مالِک خُدائ د لارو او حکمونو نه خبر وى.“ خو افسوس چې دې مشرانو هم د مالِک خُدائ د تابعدارۍ زنځير او جغ مات کړو او د خپلو ځانونو نه يې اخوا کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17951, 'Jeremiah 5:6', 'Jeremiah', 5, 6, '&nbsp;نو په دې وجه به د ځنګل نه زمرے راشى او دوئ به وخورى، او د دشتو نه به ليوۀ راشى او دوئ به برباد کړى، او پړانګ به ورته پټ کښېنى ترڅو چې څوک هم د ښار نه رابهر شى نو هغه به ټوټې ټوټې کړى. ځکه چې هغوئ غټ سرکشه دى او په څو ځله مرتد شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17952, 'Jeremiah 5:7', 'Jeremiah', 5, 7, '&nbsp;مالِک خُدائ وفرمائيل، ”زۀ څنګه تاسو معاف کړم؟ ستاسو بچو زۀ پرېښے يم او دوئ په هغه معبودانو يقين وکړو چې په حقيقت کښې هغه رښتينى نۀ دى. کۀ څۀ هم ما د هغوئ ټول ضرورتونه پوره کړل، خو هغوئ لکه د بې‌وفا ښځې په شان زنا وکړه او د چکلې مخې ته يې قطارونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17953, 'Jeremiah 5:8', 'Jeremiah', 5, 8, '&nbsp;دوئ لکه د ښۀ څربه مستو آسونو په شان دى چې هر يو د خپل ګاونډى د ښځې پسې هڼيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17954, 'Jeremiah 5:9', 'Jeremiah', 5, 9, '&nbsp;مالِک خُدائ فرمائى، ”ولې زۀ دوئ ته د دې بې‌شرمه کارونو په وجه سزا ورنۀ کړم څۀ؟ او ولې د داسې قوم نه بدله وانۀ خلم څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17955, 'Jeremiah 5:10', 'Jeremiah', 5, 10, '&nbsp;لاړ شئ او د هغوئ د انګورو باغونه تالا والا کړئ خو بلکل په پوره توګه يې مۀ تباه کوئ. او د انګور بوټى څانګې راماتې کړئ، ځکه چې دا خلق زما نۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17956, 'Jeremiah 5:11', 'Jeremiah', 5, 11, '&nbsp;مالِک خُدائ دا فرمائى، ”د اِسرائيل او يهوداه خلقو ما سره هر قسمه بې‌وفائى او خيانت کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17957, 'Jeremiah 5:12', 'Jeremiah', 5, 12, '&nbsp;دوئ د مالِک خُدائ په حقله دروغ ووئيل او وائى، ”هغه به مونږ سره هيڅ هم نۀ کوى. په مونږ به مصيبت نۀ راځى. قحط او جنګ به هم په مونږ باندې نۀ راځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17958, 'Jeremiah 5:13', 'Jeremiah', 5, 13, '&nbsp;دوئ وائى، ”پېغمبران هسې فضول خبرې کوى او دوئ سره د خُدائ پاک له طرف نه پېغام نشته. د کوم مصيبت نه چې مونږ يروى هغه دې په دوئ باندې په خپله راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17959, 'Jeremiah 5:14', 'Jeremiah', 5, 14, '&nbsp;نو ځکه مالِک خُدائ ربُ الافواج خُدائ فرمائى، ”اے يرمياه، نو لکه څنګه چې دوئ داسې خبرې کوى نو زۀ هم خپل کلام ستا په خولۀ کښې لکه د اور په شان اچوم او دوئ نه خشاک جوړوم چې دوئ وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17960, 'Jeremiah 5:15', 'Jeremiah', 5, 15, '&nbsp;مالِک خُدائ فرمائى، اے اِسرائيله، زۀ به د لرې ځائ نه ستا خلاف يو زورَور او پخوانے قوم راولېږم چې په تا حمله وکړى چې تۀ يې په ژبه او خبرو باندې نۀ پوهېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17961, 'Jeremiah 5:16', 'Jeremiah', 5, 16, '&nbsp;د هغوئ سره وژونکى غشى دى او ټول تکړه او زورَور فوجيان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17962, 'Jeremiah 5:17', 'Jeremiah', 5, 17, '&nbsp;هغوئ به ستاسو فصلونه او خوراک لواړ تېر کړى، هغوئ به ستاسو زامن او لوڼه ووژنى. هغوئ به ستاسو رَمې او څاروى تباه کړى، او هغوئ به ستاسو د انګورو او د اينځر ونې تباه کړى. تاسو چې په کومو محفوظو ښارونو باندې بهروسه کوئ نو د هغې لښکرې به يې تباه برباد کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17963, 'Jeremiah 5:18', 'Jeremiah', 5, 18, '&nbsp;مالِک خُدائ فرمائى چې، خو بيا هم په هغه ورځو کښې به زۀ تاسو په مکمل توګه نۀ تباه کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17964, 'Jeremiah 5:19', 'Jeremiah', 5, 19, '&nbsp;اے يرمياه کۀ چرې خلق تا نه تپوس وکړى چې دا هر څۀ زمونږ مالِک خُدائ پاک ولې مونږ سره وکړل؟ نو تۀ دوئ ته ووايه، چې تاسو خپل حقيقى خُدائ پرېښودو او د هغۀ په ځائ مو په خپل مُلک کښې د غېرو معبودانو خِدمت وکړو، نو په دې وجه به تاسو په پردى وطن کښې د پردو خلقو خِدمت وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17965, 'Jeremiah 5:20', 'Jeremiah', 5, 20, '&nbsp;مالِک خُدائ وفرمائيل چې، ”د يعقوب اولاد ته اعلان وکړه، د يهوداه خلقو ته ووايه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17966, 'Jeremiah 5:21', 'Jeremiah', 5, 21, '&nbsp;اے کم عقلو او بې‌شعوره خلقو، تاسو سترګې لرئ خو وينئ نه او غوږونه لرئ خو اورئ نه، ما ته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17967, 'Jeremiah 5:22', 'Jeremiah', 5, 22, '&nbsp;مالِک خُدائ فرمائى، تاسو به زما نه نۀ يرېږئ څۀ؟ تاسو به زما په حضور کښې د يرې نه نۀ ريږدېږئ څۀ؟ ما د سمندر دپاره د شګو حد مقرر کړے دے، دا مې ورته ابدى او پوخ حد مقرر کړے دے. کله چې سمندر په زور او مستۍ کښې هم راشى او د هغې چپې ډېر شور او زور هم وکړى خو بيا هم د مقرر شوى حد نه نۀ شى اوړېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17968, 'Jeremiah 5:23', 'Jeremiah', 5, 23, '&nbsp;خو زما قوم سرکشه او د ضدناکو زړونو لرونکى دى. دوئ زما نه واوړېدل او زۀ يې پرېښودلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17969, 'Jeremiah 5:24', 'Jeremiah', 5, 24, '&nbsp;دوئ هيڅکله خپل ځان سره دا نۀ دى وئيلى چې، راځئ د مالِک خُدائ نه يره وکړُو، څوک چې په مونږ باندې د منى او سپرلى موسم کښې بارانونه راوروى، او هغه مونږ ته د رېبلو موسم په مقرره وخت کښې راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17970, 'Jeremiah 5:25', 'Jeremiah', 5, 25, '&nbsp;ستاسو غلطيانو تاسو د دې عجيبه برکتونو نه محرومه کړئ. ستاسو ګناهونو تاسو د دې ښۀ څيزونو نه منع کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17971, 'Jeremiah 5:26', 'Jeremiah', 5, 26, '&nbsp;زما د غوره شوى قوم په مينځ کښې شريران پېدا کيږى. هغوئ لکه د مارغانو د ښکاريانو په شان په انتظار کښې ناست دى، دوئ د خلقو دپاره دام خوروى ترڅو هغوئ په کښې راګېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17972, 'Jeremiah 5:27', 'Jeremiah', 5, 27, '&nbsp;لکه څنګه چې د يو ښکارى پنجره د مارغانو نه ډکه وى، نو هم دغه شان د دوئ کور هم د شرارت او فساد نه ډک وى. هم دا وجه ده چې دوئ ډېر زورَور او مالداره شوى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17973, 'Jeremiah 5:28', 'Jeremiah', 5, 28, '&nbsp;ښۀ خورى او څربه کيږى او د هغوئ د بدو کارونو څۀ حد نشته دے. او نۀ هغوئ د يتيمانانو سره مدد کوى چې ورته هغه څۀ مِلاو شى کوم يې چې حق دے، او نۀ د غريبانانو مدد کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17974, 'Jeremiah 5:29', 'Jeremiah', 5, 29, '&nbsp;نو مالِک خُدائ فرمائى چې، آيا زۀ دوئ ته په دې بدو کارونو کولو سره سزا ورنۀ کړم څۀ؟ او د داسې قوم نه بدله وانۀ خلم څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17975, 'Jeremiah 5:30', 'Jeremiah', 5, 30, '&nbsp;کوم کارونه چې په دې مُلک کښې وشو هغه خراب او قابل نفرت دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17976, 'Jeremiah 5:31', 'Jeremiah', 5, 31, '&nbsp;پېغمبران د دروغو پېغامونه ورکوى، او اِمامان هم د خپلې مرضۍ حکومت کوى. او زما غوره شوے قوم هم دا سلوک خوښوى. نو تۀ ما ته دا ووايه چې هرکله دا هر څۀ ختم شى نو تاسو به څۀ کوئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17977, 'Jeremiah 6:1', 'Jeremiah', 6, 1, '&nbsp;اے د بنيامين خلقو، د خپل ځان د بچ کېدو دپاره منډه کړئ او د يروشلم نه وتښتئ. په تقوع کښې بيګل وغږوئ او په بيت‌هکرم کښې د خطرې اعلان وکړئ. ځکه چې د شمال طرف نه لوئ افت او بربادى راروانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17978, 'Jeremiah 6:2', 'Jeremiah', 6, 2, '&nbsp;زما د صيون ښکلې او نازکې لورې تۀ زما خوښه يې خو زۀ به دې تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17979, 'Jeremiah 6:3', 'Jeremiah', 6, 3, '&nbsp;تا به دشمن داسې محاصره کړى لکه څنګه چې شپانو د ښار نه ګېرچاپېره خېمې لګولې وى. هر يو به خپل فوجى ته د تباه کولو ځائ ورښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17980, 'Jeremiah 6:4', 'Jeremiah', 6, 4, '&nbsp;دوئ به چغې وهى، ”راشئ او د جنګ دپاره تيار شئ. راځئ چې مونږ د غرمې په وخت حمله وکړُو. خو افسوس چې اوس ډېر ناوخته شو، د ورځ رڼا په ختمېدو شوه، او د ماښام تيارې راخورې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17981, 'Jeremiah 6:5', 'Jeremiah', 6, 5, '&nbsp;راځئ چې د شپې په تيارۀ کښې حمله وکړُو او ټول محلونه يې تباه کړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17982, 'Jeremiah 6:6', 'Jeremiah', 6, 6, '&nbsp;مالِک ربُ الافواج خُدائ فرمائى چې، ”ونې يې ووهئ، او د خاورو د ډېرو نه د يروشلم محاصره وکړئ. دې ښار ته دې سزا ورکړے شى، ځکه چې په دې کښې د ظلم او زياتى نه بغېر نور څۀ په نظر نۀ راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17983, 'Jeremiah 6:7', 'Jeremiah', 6, 7, '&nbsp;لکه څنګه چې د يو کوهى نه تازه اوبۀ راوځى، دغه شان د دې ښار نه تازه تازه فساد او شرارت راوځى. د دې ښار په هرې خوا او ګوټونو او کوڅو کښې د ظلم او زياتى آوازونه اورېدلے کيږى. د دې ښار بيمارى او زخمونه هر وخت زما د سترګو د وړاندې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17984, 'Jeremiah 6:8', 'Jeremiah', 6, 8, '&nbsp;اے د يروشلم خلقو د دې خبردارى نه سبق حاصل کړئ، کۀ زۀ تاسو نه لاس په سر شم، نو ستاسو ښار به تباه کړم، او هغه به نور د اوسېدو قابل نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17985, 'Jeremiah 6:9', 'Jeremiah', 6, 9, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى، ”تر دې چې کوم کسان په اِسرائيل کښې پاتې شوى دى هغوئ به دوباره راوشوکولے شى، لکه څنګه چې باغوان دوباره په بوټى کښې د پاتې شوو انګورو دانو د راشوکولو لټون کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17986, 'Jeremiah 6:10', 'Jeremiah', 6, 10, '&nbsp;ما ورته ووئيل، ”چا سره زۀ خبرې وکړم، چا ته خبردارے ورکړم؟ څوک به ما ته غوږ ونيسى؟ هغوئ خپل غوږونه کاڼۀ کړى دى او هغوئ اورېدل نۀ غواړى. دوئ د مالِک خُدائ کلام پورې خندا کوى. او په هغې خوشحاليږى نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17987, 'Jeremiah 6:11', 'Jeremiah', 6, 11, '&nbsp;نو د دې دپاره زۀ د مالِک خُدائ د قهر نه ډک شوے يم، او د برداشت نه بهر شوے يم.“ مالِک خُدائ ما ته وفرمائيل چې، ”زۀ خپله غصه په کوڅو کښې په ماشومانو او د زلمو په ډلو او په ښځې او خاوند او په سپين‌ږيرو او بوډاګانو نازلوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17988, 'Jeremiah 6:12', 'Jeremiah', 6, 12, '&nbsp;مالِک خُدائ فرمائى چې، ”د هغوئ کورونه او زمکې سره د هغوئ د ښځو نورو ته حواله کړم، ځکه چې زۀ به خپل لاس د دې مُلک د خلقو په خلاف وراوږد کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17989, 'Jeremiah 6:13', 'Jeremiah', 6, 13, '&nbsp;د ماشومانو نه واخله تر بوډاګانو پورې هر يو د ناجائزه ګټې په لالچ کښې دى، د ‎پېغمبر نه واخله تر اِمام پورې ټول دوکه ماران دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17990, 'Jeremiah 6:14', 'Jeremiah', 6, 14, '&nbsp;هغوئ زما د خلقو د سختو زخمونو عرضى علاج کوى. او کله چې خير نۀ وى نو هغوئ وائى چې، خير دے، خير به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17991, 'Jeremiah 6:15', 'Jeremiah', 6, 15, '&nbsp;آيا هغوئ په خپل دې پليت عمل شرمېدل څۀ؟ نه، هغوئ بلکل شرم نۀ لرلو، هغوئ په دې هم نۀ پوهيږى چې شرم څۀ ته وائى. دوئ به د تباه شوو په مينځ کښې حساب شى. زۀ به دوئ هم ختم کړم کله چې زۀ هغوئ ته سزا ورکوم،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17992, 'Jeremiah 6:16', 'Jeremiah', 6, 16, '&nbsp;مالِک خُدائ داسې فرمائى چې، ”لاړ شئ او په چوکونو کښې ودرېږئ او ګورئ. د پخوانو او هغه لارو تپوس وکړئ کومې چې د خير طرف ته ځى. په دې لاره باندې تلل به تاسو ته خير درکړى. خو تاسو ووئيل، ”نه، مونږ به په دې باندې نۀ ځُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17993, 'Jeremiah 6:17', 'Jeremiah', 6, 17, '&nbsp;بيا ما په تاسو باندې محافظان مقرر کړل چا چې به تاسو ته وئيل، د بيګل آواز ته غوږ ونيسئ. خو تاسو ووئيل چې، نه مونږ به ورته توجو نۀ ورکوو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17994, 'Jeremiah 6:18', 'Jeremiah', 6, 18, '&nbsp;نو د دې دپاره تاسو واورئ اے قومونو، او سوچ وکړئ، اے ګواهانو چې دوئ سره به څۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17995, 'Jeremiah 6:19', 'Jeremiah', 6, 19, '&nbsp;اے د دُنيا قومونو غوږ شئ، زۀ په دې خلقو افت راولم، کوم چې د دوئ د خپلو منصوبو مېوه ده، ځکه چې دوئ زما کلام ته توجو ورنۀ کړه او زما شريعت يې رد کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17996, 'Jeremiah 6:20', 'Jeremiah', 6, 20, '&nbsp;نو بيا يې څۀ فائده ده چې دوئ د شيبا نه ما ته عطر راوړى دى، او يا د لرې مُلکونه نه قيمتى خوشبودارې مصالحې راوړى دى. زۀ به ستاسو سوزېدونکې نذرانې نۀ قبلوم. ستاسو په قربانو زۀ نۀ خوشحالېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17997, 'Jeremiah 6:21', 'Jeremiah', 6, 21, '&nbsp;نو ځکه مالِک خُدائ فرمائى، زۀ به د دې خلقو په لارو کښې د تيندک خوړلو کاڼے ولګوم چې دوئ پرې تيندک وخورى او راپرېوځى. ترڅو پلار او زامن او ګاونډيان او دوستان پرې په شريکه راپرېوځى او هلاک شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17998, 'Jeremiah 6:22', 'Jeremiah', 6, 22, '&nbsp;مالِک خُدائ فرمائى، ”د شمال د مُلک د خوا نه فوج راروان دے، او ستاسو خلاف يو لوئ او تکړه قوم د لرې نه د جنګ کولو په نيت راپاڅېدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17999, 'Jeremiah 6:23', 'Jeremiah', 6, 23, '&nbsp;هغوئ په ليندو او نېزو سره سمبال دى، هغوئ ټول ظالمان او بې‌رحمه دى. ټول جنګيالى يې په آسونو سوارۀ او په جنګى صف بندۍ کښې راروان دى او د هغوئ شور لکه د غضبناک سمندر په شان دے او په تا، صيون لورې، د حملې کولو دپاره تيار دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18000, 'Jeremiah 6:24', 'Jeremiah', 6, 24, '&nbsp;”کله چې مونږ د دوئ په حقله واورېدل، نو زمونږ لاسونو همت پرېښودلو او په لړزېدو شول. لکه څنګه چې يوې ښځې ته د لنګون درد شروع شى دغه شان درد، يرې او وحشت راواخستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');